<?php
$mrr=(int)value("SELECT COALESCE(SUM(p.price),0) FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE s.status='active' AND s.is_trial=0 AND s.ends_at>NOW()");$paidUsers=(int)value("SELECT COUNT(DISTINCT user_id) FROM payments WHERE status='paid'");$revenue=(int)value("SELECT COALESCE(SUM(amount),0) FROM payments WHERE status='paid'");$cancelled=(int)value("SELECT COUNT(*) FROM subscriptions WHERE status='cancelled'");$monthlyCancelled=(int)value("SELECT COUNT(*) FROM subscriptions WHERE cancelled_at>=DATE_FORMAT(NOW(),'%Y-%m-01')");$atStart=(int)value("SELECT COUNT(*) FROM subscriptions s JOIN plans p ON p.id=s.plan_id WHERE p.price>0 AND s.is_trial=0 AND s.starts_at<DATE_FORMAT(NOW(),'%Y-%m-01') AND s.ends_at>=DATE_FORMAT(NOW(),'%Y-%m-01') AND (s.cancelled_at IS NULL OR s.cancelled_at>=DATE_FORMAT(NOW(),'%Y-%m-01'))");
?><div class="card stack"><h3>Revenue measures</h3><p class="small">MRR is the current monthly plan-price run rate, excluding trials. Plans renew manually. ARR is a 12× run-rate estimate, not booked revenue. Payment totals reflect verified captured payments.</p><?php table(['metric'=>'Metric','value'=>'Value'],[['metric'=>'MRR run rate','value'=>money($mrr)],['metric'=>'ARR estimate','value'=>money($mrr*12)],['metric'=>'All-time captured revenue','value'=>money($revenue)],['metric'=>'Average captured revenue per paying customer','value'=>$paidUsers?money((int)round($revenue/$paidUsers)):'—'],['metric'=>'Cancelled subscriptions','value'=>$cancelled],['metric'=>'Cancellations this month','value'=>$monthlyCancelled],['metric'=>'Monthly cancellation rate','value'=>$atStart?round($monthlyCancelled/$atStart*100,1).'%':'No opening cohort']]);?></div>
